Mashup.mashupContent:
{ "CustomMashupCss": "/* Shared Git workspace tokens and layout.

 Spacing rule: every visible widget keeps ThingWorx's default Margin of 5,
 so neighbouring controls sit 10px apart. Card containers also use Margin 5
 so their edges line up with text. Container padding and gaps below subtract
 that 5px, so the visible insets are 24px at the page edge and 16px between
 sections and inside cards. Do not give individual widgets other margins;
 align rows with the container's align-items instead (flex-end for rows with
 labelled inputs, center for buttons and checkboxes).

 Contrast (WCAG): text 11.4:1 and muted text 5.2:1 on the canvas; muted text
 5.9:1 on surfaces. Native widget colors and focus indicators stay with the
 active ThingWorx theme. The theme's container style sets a white
 background, so backgrounds and borders below need !important. */
:root {
 --git-text: #243746;
 --git-muted: #536776;
 --git-canvas: #eef1f4;
 --git-surface: #ffffff;
 --git-border: #c2cbd3;
 --git-radius: 6px;
 --git-page-inset: 19px; /* + 5px widget margin = 24px */
 --git-card-inset: 11px; /* + 5px widget margin = 16px */
 --git-section-gap: 6px; /* + 5px + 5px margins = 16px */
 --git-header-height: 64px;
}

/* Header band: the slot that holds GIT.Mashup.GitHeader on every page. The
 runtime sizes a contained mashup to fill its slot, so GitHeader applies its
 own horizontal inset (see GitHeader.css). */
[id$="git-header-slot"] {
 min-height: var(--git-header-height);
 background: var(--git-surface) !important;
 border-bottom: 1px solid var(--git-border) !important;
 color: var(--git-text);
 box-sizing: border-box;
}

/* Page body. */
[id$="home-main"],
[id$="changes-main"],
[id$="branches-main"],
[id$="history-main"],
[id$="log-main"],
[id$="reflog-main"],
[id$="extlog-main"],
[id$="settings-main"],
[id$="create-main"],
[id$="user-settings-content"],
[id$="operations-main"],
[id$="conflictresolution-main"] {
 padding: var(--git-page-inset);
 gap: var(--git-section-gap);
 align-items: stretch !important;
 background: var(--git-canvas) !important;
 color: var(--git-text);
 box-sizing: border-box;
}

/* Layout containers inside the page stay transparent; only cards are white. */
:is([id$="home-main"], [id$="changes-main"], [id$="branches-main"], [id$="history-main"], [id$="log-main"], [id$="reflog-main"], [id$="extlog-main"], [id$="settings-main"], [id$="create-main"], [id$="user-settings-content"], [id$="operations-main"], [id$="conflictresolution-main"]) .widget-flexcontainer { background: transparent !important; }

/* Cards: white surfaces on the canvas. */
:is([id$="home-main"], [id$="changes-main"], [id$="branches-main"], [id$="history-main"], [id$="log-main"], [id$="reflog-main"], [id$="extlog-main"], [id$="settings-main"], [id$="create-main"], [id$="user-settings-content"], [id$="operations-main"], [id$="conflictresolution-main"]) :is([id$="home-list-container"], [id$="changes-sync-card"], [id$="changes-worktree-card"], [id$="changes-push-card"], [id$="branches-list-card"], [id$="branches-create-card"], [id$="branches-merge-card"], [id$="repository-settings-card"], [id$="repository-credentials-card"], [id$="repository-status-card"], [id$="settings-projects"], [id$="settings-projects-add"], [id$="settings-remotes"], [id$="create-repository-card"], [id$="create-credentials-card"], [id$="create-projects-card"], [id$="create-advanced-card"], [id$="history-tree-card"], [id$="history-log-card"]),
[id$="user-settings-content"] :is([id$="flexcontainer-40"], [id$="flexcontainer-41"], [id$="ssh-keys-section"], [id$="ssh-add-section"], [id$="identity-section"], [id$="extension-log-section"]) {
 background: var(--git-surface) !important;
 border: 1px solid var(--git-border) !important;
 border-radius: var(--git-radius) !important;
 box-sizing: border-box;
 min-width: 0;
}
/* User Settings sections use the shared card inset. */
[id$="user-settings-content"] :is([id$="flexcontainer-40"], [id$="flexcontainer-41"], [id$="ssh-keys-section"], [id$="ssh-add-section"], [id$="identity-section"], [id$="extension-log-section"]) { padding: var(--git-card-inset); }

/* One scroller per page: the *-main body. The runtime gives every bounding box
 min-height: 0 and container bounding boxes max-height: 100%, so on a short
 viewport (e.g. 150% display scaling) cards shrink and each grows its own
 scrollbar. Keep the body's direct children at their content height instead. */
:is([id$="home-main"], [id$="changes-main"], [id$="branches-main"], [id$="history-main"], [id$="log-main"], [id$="reflog-main"], [id$="extlog-main"], [id$="settings-main"], [id$="create-main"], [id$="user-settings-content"], [id$="operations-main"], [id$="conflictresolution-main"]) > .widget-bounding-box { flex-shrink: 0 !important; max-height: none !important; }

/* Grid areas: the grid draws its own border, so only size them. */
[id$="changes-grid-area"],
[id$="branches-grid-area"],
[id$="log-grid-area"],
[id$="reflog-grid-area"],
[id$="extlog-grid-area"] { min-height: 320px; min-width: 0; }
[id$="changes-grid-bounding-box"],
[id$="log-grid-bounding-box"],
[id$="reflog-grid-bounding-box"],
[id$="extlog-grid-bounding-box"] { position: relative; flex: 1 1 0%; min-width: 0; }

/* Secondary text. */
[id$="-intro"],
[id$="-status"] { color: var(--git-muted); line-height: 1.5; }

@media (max-width: 600px) {
 :root { --git-page-inset: 11px; } /* 16px visible */
}

/* New repository form: each section is a card; fields keep a readable width. */
[id$="create-repository-card"],
[id$="create-credentials-card"],
[id$="create-projects-card"],
[id$="create-advanced-card"] {
 align-self: stretch !important;
 padding: var(--git-card-inset);
}
[id$="create-projects-grid-area"] { align-self: stretch; min-height: 240px; min-width: 0; }
[id$="create-message"] { color: var(--git-text); }", "Data": {}, "DataBindings": [ { "Id": "c08d1e12-30f2-4e1a-9585-8fba639c51de", "PropertyMaps": [ { "SourceProperty": "keyOptions", "SourcePropertyBaseType": "INFOTABLE", "SourcePropertyType": "Property", "TargetProperty": "Data", "TargetPropertyBaseType": "INFOTABLE", "TargetPropertyType": "property" } ], "SourceArea": "UI", "SourceDetails": "", "SourceId": "repository-create-helper", "SourceSection": "", "TargetArea": "UI", "TargetId": "create-key", "TargetSection": "" }, { "Id": "2df4f5b8-d234-4733-b6fa-fbe10dc68bae", "PropertyMaps": [ { "SourceProperty": "availableProjects", "SourcePropertyBaseType": "INFOTABLE", "SourcePropertyType": "Property", "TargetProperty": "Data", "TargetPropertyBaseType": "INFOTABLE", "TargetPropertyType": "property" } ], "SourceArea": "UI", "SourceDetails": "", "SourceId": "repository-create-helper", "SourceSection": "", "TargetArea": "UI", "TargetId": "create-projects-grid", "TargetSection": "" }, { "Id": "d36521ae-9080-4651-a636-1e59dff0f41a", "PropertyMaps": [ { "SourceProperty": "SelectedRows", "SourcePropertyBaseType": "INFOTABLE", "SourcePropertyType": "Property", "TargetProperty": "selectedProjects", "TargetPropertyBaseType": "INFOTABLE", "TargetPropertyType": "property" } ], "SourceArea": "UI", "SourceDetails": "", "SourceId": "create-projects-grid", "SourceSection": "", "TargetArea": "UI", "TargetId": "repository-create-helper", "TargetSection": "" }, { "Id": "317e6f9f-833e-46ba-a6bf-424f69381c9c", "PropertyMaps": [ { "SourceProperty": "message", "SourcePropertyBaseType": "STRING", "SourcePropertyType": "Property", "TargetProperty": "LabelText", "TargetPropertyBaseType": "STRING", "TargetPropertyType": "property" } ], "SourceArea": "UI", "SourceDetails": "", "SourceId": "repository-create-helper", "SourceSection": "", "TargetArea": "UI", "TargetId": "create-message", "TargetSection": "" }, { "Id": "6d09d3fb-172b-4552-8e10-0be3a8214705", "PropertyMaps": [ { "SourceProperty": "p